// Responsive photo: WebP variants (generated by `npm run images`) with the
// original JPEG as fallback. `src` is the JPEG path, e.g. "/img/achu.jpg".
export default function Picture({
  src,
  alt,
  sizes = "(max-width: 640px) 100vw, 480px",
  className,
  loading = "lazy",
  fetchPriority,
  width,
  height,
}) {
  const base = src.replace(/\.jpe?g$/i, "");
  const hasVariants = base !== src;

  return (
    <picture>
      {hasVariants ? (
        <source type="image/webp" srcSet={`${base}-480.webp 480w, ${base}-960.webp 960w`} sizes={sizes} />
      ) : null}
      <img
        src={src}
        alt={alt}
        className={className}
        loading={loading}
        decoding="async"
        fetchPriority={fetchPriority}
        width={width}
        height={height}
      />
    </picture>
  );
}
